mapper.select:
SELECT t.account_id, SUM(t.debit) AS debit, SUM(t.credit) AS credit FROM ( SELECT e.account_id, e.debit, e.credit FROM fin_voucher_entry e JOIN fin_voucher v ON v.id = e.voucher_id WHERE v.status = 'POSTED' AND v.period >= #{begin} AND v.period <= #{end} AND v.source_type <> 'CLOSE'
UNION ALL SELECT o.account_id, o.debit, o.credit FROM fin_account_opening o
) t GROUP BY t.account_id

SELECT COALESCE(SUM(t.amount), 0) FROM (
    SELECT e.debit - e.credit AS amount
    FROM fin_voucher_entry e
    JOIN fin_voucher v ON v.id = e.voucher_id
    WHERE e.account_id = #{accountId} AND v.period <= #{period}
    UNION ALL
    SELECT o.debit - o.credit FROM fin_account_opening o WHERE o.account_id = #{accountId}
) t
